#let benchmark_results_table() = {
  let data = bench_data()
  let meta = data.meta
  let dirty_tag = if "dirty" in meta and meta.dirty { [ · बदला हुआ source tree] } else { [] }
  let rows = benchmark_rows().map(((label, sub, wl, has_model)) => {
    let sib = bench_find(data, "sibuna", sub, wl)
    let model = none
    (
      [#label],
      [#fmt_ns(if sib != none { sib.ns_per_op_median } else { none })],
      [#fmt_ns(if sib != none { sib.ns_per_op_min } else { none }) – #fmt_ns(if sib != none { sib.ns_per_op_max } else { none })],
      [#fmt_int(if sib != none { sib.ops_per_sec } else { none })],
    )
  }).flatten()
  let naive = bench_find(data, "sibuna-naive", "bot_matcher", "sequential_substring_40_signatures")
  let ac = bench_find(data, "sibuna", "bot_matcher", "aho_corasick_40_signatures")
  [
    #text(size: 8pt, fill: gray)[
      दर्ज #meta.date · #meta.host · #meta.cpu · #meta.os · revision
      #raw(meta.git)#dirty_tag · Zig #meta.zig · ReleaseFast · 7 बैच, न्यूनतम–अधिकतम सीमा के साथ मध्यिका
    ]
    #v(6pt)
    #grid(
      columns: (1fr, 1fr, 1fr, 1fr),
      gutter: 6pt,
      stat_tile([#fmt_ns(bench_find(data, "sibuna", "pow_verify", "hashcash_16_bits").ns_per_op_median)], [Hashcash की जाँच],
        [Hardware SHA-256, कोई allocation नहीं], fill: blue_light, stroke: blue),
      stat_tile([#fmt_ns(bench_find(data, "sibuna", "token_auth", "blake3_mac_token").ns_per_op_median)], [सेशन टोकन की जाँच],
        [Keyed BLAKE3, 75-अक्षरों की Cookie], fill: green_light, stroke: green),
      stat_tile([#calc.round(meta.idle_rss_kb / 1024, digits: 1) MiB], [निष्क्रिय अवस्था में resident memory],
        [शुरू होने के बाद daemon, storage बंद], fill: amber_light, stroke: amber),
      stat_tile([#calc.round(meta.binary_bytes / 1048576, digits: 1) MiB], [Daemon की executable फ़ाइल],
        [WASM में हल करने वाला प्रोग्राम: #meta.wasm_bytes bytes], fill: rgb("f5f3ff"), stroke: rgb("7c3aed")),
    )
    #v(8pt)
    #block(width: 100%, inset: 10pt, radius: 5pt, fill: blue_light, stroke: 0.5pt + rule)[
      #text(size: 11pt, weight: "bold")[हर operation की मापी गई latency]
      #linebreak()
      #text(size: 8pt, fill: gray)[यहाँ केवल primitives की मापी गई latency है। Allocation की गतिविधि को मापने के लिए instrumentation नहीं है।]
      #v(5pt)
      #table(
        columns: (1.6fr, 0.8fr, 1fr, 0.8fr),
        table.header([*कार्यभार*], [*मध्यिका*], [*न्यूनतम–अधिकतम*], [*ops/s*]),
        ..rows,
      )
      #v(4pt)
      #text(size: 8pt, fill: gray)[तुलना के लिए, इसी host पर उन्हीं 40 bot signatures को sequential substring search से जाँचने में #fmt_ns(naive.ns_per_op_median) लगे। Automaton के लिए #fmt_ns(ac.ns_per_op_median) लगे।]
    ]
  ]
}

